template <typename T>
__device__ __forceinline__ const T* poly_raw_ptr(int k, long s, long d, const T* a, const T* b, const T* c,
                                                 int K3, int K2, int K1, int C) {
    if (k < K3) return a + ((s * K3 + k) * C + d);
    if (k < K3 + K2) return b + ((s * K2 + (k - K3)) * C + d);
    return c + ((s * K1 + (k - K3 - K2)) * C + d);
}

template <typename T>
__global__ void k_cat_w_u(T* __restrict__ Wu, const T* __restrict__ a, const T* __restrict__ b,
                          const T* __restrict__ c, int S, int K, int K3, int K2, int C) {
    const long i = (long)blockIdx.x * blockDim.x + threadIdx.x;
    const long SC = (long)S * C;
    if (i >= SC) return;
    const long s = i / C, d = i % C;
    const int K1 = K - K3 - K2;
    T* wd = Wu + s * POLY_U * C + d;
    wd[0 * C] = *poly_raw_ptr(0, s, d, a, b, c, K3, K2, K1, C);
    wd[1 * C] = *poly_raw_ptr(1, s, d, a, b, c, K3, K2, K1, C) + *poly_raw_ptr(4, s, d, a, b, c, K3, K2, K1, C) + *poly_raw_ptr(5, s, d, a, b, c, K3, K2, K1, C);
    wd[2 * C] = *poly_raw_ptr(2, s, d, a, b, c, K3, K2, K1, C) + *poly_raw_ptr(10, s, d, a, b, c, K3, K2, K1, C) + *poly_raw_ptr(13, s, d, a, b, c, K3, K2, K1, C);
    wd[3 * C] = *poly_raw_ptr(3, s, d, a, b, c, K3, K2, K1, C) + *poly_raw_ptr(17, s, d, a, b, c, K3, K2, K1, C) + *poly_raw_ptr(21, s, d, a, b, c, K3, K2, K1, C);
    wd[4 * C] = *poly_raw_ptr(6, s, d, a, b, c, K3, K2, K1, C) + *poly_raw_ptr(7, s, d, a, b, c, K3, K2, K1, C) + *poly_raw_ptr(11, s, d, a, b, c, K3, K2, K1, C);
    wd[5 * C] = *poly_raw_ptr(8, s, d, a, b, c, K3, K2, K1, C) + *poly_raw_ptr(9, s, d, a, b, c, K3, K2, K1, C) + *poly_raw_ptr(12, s, d, a, b, c, K3, K2, K1, C) + *poly_raw_ptr(15, s, d, a, b, c, K3, K2, K1, C) + *poly_raw_ptr(18, s, d, a, b, c, K3, K2, K1, C) + *poly_raw_ptr(19, s, d, a, b, c, K3, K2, K1, C);
    wd[6 * C] = *poly_raw_ptr(14, s, d, a, b, c, K3, K2, K1, C);
    wd[7 * C] = *poly_raw_ptr(16, s, d, a, b, c, K3, K2, K1, C) + *poly_raw_ptr(20, s, d, a, b, c, K3, K2, K1, C) + *poly_raw_ptr(22, s, d, a, b, c, K3, K2, K1, C);
    wd[8 * C] = *poly_raw_ptr(23, s, d, a, b, c, K3, K2, K1, C);
    wd[9 * C] = *poly_raw_ptr(24, s, d, a, b, c, K3, K2, K1, C);
    wd[10 * C] = *poly_raw_ptr(25, s, d, a, b, c, K3, K2, K1, C);
    wd[11 * C] = *poly_raw_ptr(26, s, d, a, b, c, K3, K2, K1, C);
    wd[12 * C] = *poly_raw_ptr(27, s, d, a, b, c, K3, K2, K1, C);
}

template <typename T>
__global__ void k_uncat_gw_u(const T* __restrict__ gWu, T* __restrict__ a, T* __restrict__ b,
                             T* __restrict__ c, int S, int K, int K3, int K2, int C) {
    const long i = (long)blockIdx.x * blockDim.x + threadIdx.x;
    if (i >= (long)S * K * C) return;
    const long s = i / ((long)K * C), k = (i / C) % K, d = i % C;
    const int K1 = K - K3 - K2;
    const T v = gWu[(s * POLY_U + POLY_K_TO_U[k]) * C + d];
    if (k < K3) a[(s * K3 + k) * C + d] = v;
    else if (k < K3 + K2) b[(s * K2 + (k - K3)) * C + d] = v;
    else c[(s * K1 + (k - K3 - K2)) * C + d] = v;
}

template <typename T>
__global__ void k_cat_w_u_pair(T* __restrict__ Wu0, const T* __restrict__ a0, const T* __restrict__ b0,
                               const T* __restrict__ c0, T* __restrict__ Wu1, const T* __restrict__ a1,
                               const T* __restrict__ b1, const T* __restrict__ c1, int S, int K, int K3, int K2,
                               int C) {
    const long i = (long)blockIdx.x * blockDim.x + threadIdx.x;
    const long SC = (long)S * C;
    if (i >= SC) return;
    const bool l1 = (blockIdx.y != 0);
    T* Wu = l1 ? Wu1 : Wu0;
    const T* a = l1 ? a1 : a0;
    const T* b = l1 ? b1 : b0;
    const T* c = l1 ? c1 : c0;
    const long s = i / C, d = i % C;
    const int K1 = K - K3 - K2;
    T* wd = Wu + s * POLY_U * C + d;
    wd[0 * C] = *poly_raw_ptr(0, s, d, a, b, c, K3, K2, K1, C);
    wd[1 * C] = *poly_raw_ptr(1, s, d, a, b, c, K3, K2, K1, C) + *poly_raw_ptr(4, s, d, a, b, c, K3, K2, K1, C) + *poly_raw_ptr(5, s, d, a, b, c, K3, K2, K1, C);
    wd[2 * C] = *poly_raw_ptr(2, s, d, a, b, c, K3, K2, K1, C) + *poly_raw_ptr(10, s, d, a, b, c, K3, K2, K1, C) + *poly_raw_ptr(13, s, d, a, b, c, K3, K2, K1, C);
    wd[3 * C] = *poly_raw_ptr(3, s, d, a, b, c, K3, K2, K1, C) + *poly_raw_ptr(17, s, d, a, b, c, K3, K2, K1, C) + *poly_raw_ptr(21, s, d, a, b, c, K3, K2, K1, C);
    wd[4 * C] = *poly_raw_ptr(6, s, d, a, b, c, K3, K2, K1, C) + *poly_raw_ptr(7, s, d, a, b, c, K3, K2, K1, C) + *poly_raw_ptr(11, s, d, a, b, c, K3, K2, K1, C);
    wd[5 * C] = *poly_raw_ptr(8, s, d, a, b, c, K3, K2, K1, C) + *poly_raw_ptr(9, s, d, a, b, c, K3, K2, K1, C) + *poly_raw_ptr(12, s, d, a, b, c, K3, K2, K1, C) + *poly_raw_ptr(15, s, d, a, b, c, K3, K2, K1, C) + *poly_raw_ptr(18, s, d, a, b, c, K3, K2, K1, C) + *poly_raw_ptr(19, s, d, a, b, c, K3, K2, K1, C);
    wd[6 * C] = *poly_raw_ptr(14, s, d, a, b, c, K3, K2, K1, C);
    wd[7 * C] = *poly_raw_ptr(16, s, d, a, b, c, K3, K2, K1, C) + *poly_raw_ptr(20, s, d, a, b, c, K3, K2, K1, C) + *poly_raw_ptr(22, s, d, a, b, c, K3, K2, K1, C);
    wd[8 * C] = *poly_raw_ptr(23, s, d, a, b, c, K3, K2, K1, C);
    wd[9 * C] = *poly_raw_ptr(24, s, d, a, b, c, K3, K2, K1, C);
    wd[10 * C] = *poly_raw_ptr(25, s, d, a, b, c, K3, K2, K1, C);
    wd[11 * C] = *poly_raw_ptr(26, s, d, a, b, c, K3, K2, K1, C);
    wd[12 * C] = *poly_raw_ptr(27, s, d, a, b, c, K3, K2, K1, C);
}

template <typename T>
__global__ void k_uncat_gw_u_pair(const T* __restrict__ gWu0, T* __restrict__ a0, T* __restrict__ b0,
                                  T* __restrict__ c0, const T* __restrict__ gWu1, T* __restrict__ a1,
